package com.coffeeshop.repository;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.NotificationModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcNotificationRepository implements NotificationRepository{private final DataSource ds;public JdbcNotificationRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<NotificationModels.Notification>find(long user,Boolean read){String q="SELECT notification_id,notification_type,title,message_body,related_entity_type,related_entity_id,is_read,read_at,expires_at,created_at,row_version FROM dbo.notifications WHERE (recipient_user_id IS NULL OR recipient_user_id=?) AND (? IS NULL OR is_read=?) AND (expires_at IS NULL OR expires_at>SYSUTCDATETIME()) ORDER BY is_read,created_at DESC";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,user);if(read==null){s.setNull(2,Types.BIT);s.setNull(3,Types.BIT);}else{s.setBoolean(2,read);s.setBoolean(3,read);}try(ResultSet r=s.executeQuery()){List<NotificationModels.Notification>x=new ArrayList<>();while(r.next()){Long entity=r.getObject(6,Long.class);Timestamp readAt=r.getTimestamp(8),expires=r.getTimestamp(9);x.add(new NotificationModels.Notification(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),entity,r.getBoolean(7),readAt==null?null:readAt.toLocalDateTime(),expires==null?null:expires.toLocalDateTime(),r.getTimestamp(10).toLocalDateTime(),r.getBytes(11)));}return List.copyOf(x);}}catch(SQLException e){throw fail("Unable to load notifications.",e);}}public void markRead(long id,long user,byte[]v){String q="UPDATE dbo.notifications SET is_read=1,read_at=SYSUTCDATETIME() WHERE notification_id=? AND (recipient_user_id IS NULL OR recipient_user_id=?) AND is_read=0 AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);s.setLong(2,user);s.setBytes(3,v);if(s.executeUpdate()!=1)throw new IllegalStateException("Notification changed. Refresh and try again.");}catch(SQLException e){throw fail("Unable to mark notification read.",e);}}public int generateLowStockAlerts(){String q="INSERT dbo.notifications(notification_type,title,message_body,related_entity_type,related_entity_id) SELECT 'LOW_STOCK','Low stock: '+i.item_name,CONCAT(i.item_name,' stock is ',i.current_stock_quantity,' ',u.unit_name,'; reorder level is ',i.reorder_level,'.'),'INVENTORY_ITEM',i.inventory_item_id FROM dbo.inventory_items i JOIN dbo.units_of_measure u ON u.unit_of_measure_id=i.unit_of_measure_id WHERE i.is_active=1 AND i.current_stock_quantity<=i.reorder_level AND NOT EXISTS(SELECT 1 FROM dbo.notifications n WITH(UPDLOCK,HOLDLOCK) WHERE n.notification_type='LOW_STOCK' AND n.related_entity_type='INVENTORY_ITEM' AND n.related_entity_id=i.inventory_item_id AND n.is_read=0 AND (n.expires_at IS NULL OR n.expires_at>SYSUTCDATETIME()))";try(Connection c=ds.getConnection()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try(PreparedStatement s=c.prepareStatement(q)){int n=s.executeUpdate();c.commit();return n;}catch(Exception e){c.rollback();throw e;}}catch(Exception e){throw fail("Unable to generate low-stock alerts.",e);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
